export function applyProvisionalPrices(products) {
  const apply = variant => {
    const basis = provisionalPrices[variant.id];
    if (!basis || variant.priceStatus !== "pending") return variant;
    const exact = basis.kind === "exact_retail";
    return { ...variant, price: basis.amount, priceStatus: "temporary",
      pricingBasis: basis,
      ...(exact ? { retailOffers: basis.offers, retailPrice: {
        amount: basis.amount, currency: "EUR", status: "temporary", type: "retail",
        sourceName: basis.offers[0].retailer, sourceUrl: basis.offers[0].url,
        checkedAt: basis.offers[0].checkedAt, taxIncluded: true, shippingIncluded: false,
      } } : {}),
    };
  };
  return products.map(product => product.variants?.length
    ? { ...product, variants: product.variants.map(apply) } : apply(product));
}
